import subprocess
import sys


def runtime_version(host):
    out = subprocess.run(['ssh', host, 'runtime', '-v'], capture_output=True, text=True, check=True)
    return out.stdout.split()[1]


def main(argv):
    for host in argv[1:]:
        print(host, runtime_version(host))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))
